    if (!binding.hasPrevious && !binding.hasNext) {
      return const SizedBox.shrink();
    }
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        TextButton(onPressed: binding.hasPrevious ? binding.previous : null, child: Text(_text('framework.previous'))),
        TextButton(onPressed: binding.hasNext ? binding.next : null, child: Text(_text('framework.next'))),
      ],
    );
  }
}

/// The element's content followed by its pager, when it has one.
Widget _paged(BuildContext context, DtxStyle? style, Widget content, PagedBinding<Object?>? pager) {
  final body = pager == null
      ? content
      : Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            content,
            DtxPager(binding: pager),
          ],
        );
  return dtxStyled(context, style, body);
}

