  @override
  void dispose() {
    _position?.removeListener(_scrolled);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final empty = widget.empty;
    final activate = widget.onActivate;
    final loader = widget.loader;
    final gap = DtxTokens.of(context).gap;
    final content = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      spacing: gap,
      children: [
        if (widget.items.isEmpty && empty != null) _Empty(empty),
        for (final entry in widget.items) MergeSemantics(child: _activatable(widget.item(entry), activate == null ? null : () => activate(entry))),
        if (loader != null && loader.hasNext) TextButton(onPressed: loader.next, child: Text(_text('framework.loadMore'))),
      ],
    );
    return dtxStyled(context, widget.style, content);
  }
}

/// Whether a timeline or calendar value is a date or a date-time.
enum DtxTimeKind { date, dateTime }

String _formatted(DateTime value, DtxTimeKind kind) {
  final locale = datrixRuntime.session.locale;
  return kind == DtxTimeKind.date ? formatDate(value, locale) : '${formatDate(value, locale)} ${formatTime(value, locale)}';
}

/// `timeline(data: items, at: e => e.when) { item template }`: the items
/// earliest first, each under its time.
class DtxTimeline<T> extends StatelessWidget {
  const DtxTimeline({super.key, required this.items, required this.at, required this.kind, required this.item, this.onActivate, this.pager, this.style});

  final List<T> items;
  final String? Function(T item) at;
  final DtxTimeKind kind;
  final Widget Function(T item) item;
  final void Function(T item)? onActivate;
  final PagedBinding<Object?>? pager;
  final DtxStyle? style;

  @override
  Widget build(BuildContext context) {
    final activate = onActivate;
    final tokens = DtxTokens.of(context);
    final entries = [
      for (final entry in items)
        if (at(entry) case final String time when time.isNotEmpty) (entry, dtxCalendarDate(time)),
    ]..sort((left, right) => left.$2.compareTo(right.$2));
    final content = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      spacing: tokens.gap,
      children: [
        for (final (entry, time) in entries)
          MergeSemantics(
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              spacing: tokens.gap,
              children: [
                Text(_formatted(time, kind), style: Theme.of(context).textTheme.labelMedium),
                Expanded(child: _activatable(item(entry), activate == null ? null : () => activate(entry))),
              ],
            ),
          ),
      ],
    );
    return _paged(context, style, content, pager);
  }
}

/// A URL that arrives as data, when it is safe to load as an image: an
/// https URL. Anything else shows no image.
String? dtxSafeImageUrl(String? value) {
  final url = value?.trim() ?? '';
  final parsed = Uri.tryParse(url);
  return parsed != null && parsed.scheme == 'https' && parsed.host.isNotEmpty ? url : null;
}

/// `gallery(data: items, image: i => i.url, caption: i => i.caption)`.
class DtxGallery<T> extends StatelessWidget {
  const DtxGallery({super.key, required this.items, required this.image, required this.caption, this.onActivate, this.pager, this.style});

  final List<T> items;
  final String? Function(T item) image;
  final String? Function(T item) caption;
  final void Function(T item)? onActivate;
  final PagedBinding<Object?>? pager;
  final DtxStyle? style;

  @override
  Widget build(BuildContext context) {
    final activate = onActivate;
    final gap = DtxTokens.of(context).gap;
    final content = Wrap(
      spacing: gap,
      runSpacing: gap,
      children: [
        for (final entry in items)
          ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: _galleryTileWidth),
            child: _activatable(_figure(context, entry), activate == null ? null : () => activate(entry)),
          ),
      ],
    );
    return _paged(context, style, content, pager);
  }

  Widget _figure(BuildContext context, T entry) {
    final url = dtxSafeImageUrl(image(entry));
    final text = caption(entry) ?? '';
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (url != null) Image.network(url, semanticLabel: text),
        Text(text, style: Theme.of(context).textTheme.bodySmall),
      ],
    );
  }
}

