/// `board(data: items, column: i => i.status) : onMove(...) { card }`.
class DtxBoard<T extends Object, C> extends StatelessWidget {
  const DtxBoard({super.key, required this.items, required this.column, required this.columns, required this.item, this.onMove, this.onActivate, this.pager, this.style});

  final List<T> items;
  final C Function(T item) column;
  final List<DtxBoardColumn<C>> columns;
  final Widget Function(T item) item;
  final void Function(T item, C column)? onMove;
  final void Function(T item)? onActivate;
  final PagedBinding<Object?>? pager;
  final DtxStyle? style;

  void _move(T entry, int columnIndex, int direction) {
    final target = columnIndex + direction;
    if (target >= 0 && target < columns.length) {
      onMove?.call(entry, columns[target].value);
    }
  }

  Widget _card(BuildContext context, T entry, int columnIndex) {
    final activate = onActivate;
    final card = Card(
      child: Padding(padding: EdgeInsets.all(DtxTokens.of(context).gap), child: item(entry)),
    );
    final focusable = Shortcuts(
      shortcuts: const <ShortcutActivator, Intent>{SingleActivator(LogicalKeyboardKey.arrowLeft): _MoveCardIntent(-1), SingleActivator(LogicalKeyboardKey.arrowRight): _MoveCardIntent(1)},
      child: Actions(
        actions: <Type, Action<Intent>>{_MoveCardIntent: CallbackAction<_MoveCardIntent>(onInvoke: (intent) => _move(entry, columnIndex, intent.direction))},
        child: Focus(child: _activatable(card, activate == null ? null : () => activate(entry))),
      ),
    );
    return LongPressDraggable<T>(
      data: entry,
      feedback: Material(
        elevation: 4,
        child: SizedBox(width: _galleryTileWidth, child: card),
      ),
      child: focusable,
    );
  }

  @override
  Widget build(BuildContext context) {
    final gap = DtxTokens.of(context).gap;
    final textTheme = Theme.of(context).textTheme;
    final board = SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        spacing: gap,
        children: [
          for (final (columnIndex, boardColumn) in columns.indexed)
            DragTarget<T>(
              onAcceptWithDetails: (details) => onMove?.call(details.data, boardColumn.value),
              builder: (context, candidates, rejected) => Semantics(
                container: true,
                label: boardColumn.label,
                explicitChildNodes: true,
                child: SizedBox(
                  width: _galleryTileWidth,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    spacing: gap,
                    children: [
                      ExcludeSemantics(child: Text(boardColumn.label, style: textTheme.titleSmall)),
                      for (final entry in items)
                        if (column(entry) == boardColumn.value) _card(context, entry, columnIndex),
                    ],
                  ),
                ),
              ),
            ),
        ],
      ),
    );
    return _paged(context, style, board, pager);
  }
}

class _MoveCardIntent extends Intent {
