}

/// What a calendar shows at once.
enum DtxCalendarMode { month, week, day }

DateTime _day(DateTime value) => DateTime(value.year, value.month, value.day);

DateTime _addDays(DateTime value, int days) => DateTime(value.year, value.month, value.day + days);

DateTime _startOfWeek(DateTime value) => _addDays(_day(value), -(value.weekday - DateTime.monday));

/// One calendar entry: its item and the days it spans.
class _CalendarEntry<T> {
  const _CalendarEntry(this.item, this.start, this.end);

  final T item;
  final DateTime start;
  final DateTime end;
}

/// `calendar(data: items, at: e => e.start, until: e => e.end?) { entry }`.
class DtxCalendar<T> extends StatefulWidget {
  const DtxCalendar({super.key, required this.items, required this.at, this.until, required this.item, this.onActivate, this.empty, this.pager, this.style});

  final List<T> items;
  final String? Function(T item) at;
  final String? Function(T item)? until;
  final Widget Function(T item) item;
  final void Function(T item)? onActivate;
  final String? empty;
  final PagedBinding<Object?>? pager;
  final DtxStyle? style;

  @override
  State<DtxCalendar<T>> createState() => _DtxCalendarState<T>();
}

class _DtxCalendarState<T> extends State<DtxCalendar<T>> {
  DtxCalendarMode _mode = DtxCalendarMode.month;
  DateTime _anchor = _day(DateTime.now());
  DateTime _focused = _day(DateTime.now());
  final FocusNode _grid = FocusNode();

  /// How far an arrow key moves the focused day, or `null` for any other key.
  static int? _step(LogicalKeyboardKey key) {
    if (key == LogicalKeyboardKey.arrowLeft) {
      return -1;
    }
    if (key == LogicalKeyboardKey.arrowRight) {
      return 1;
    }
    if (key == LogicalKeyboardKey.arrowUp) {
      return -_daysPerWeek;
    }
    if (key == LogicalKeyboardKey.arrowDown) {
      return _daysPerWeek;
    }
    return null;
  }

  @override
  void dispose() {
    _grid.dispose();
    super.dispose();
  }

  List<_CalendarEntry<T>> _entries() {
    final until = widget.until;
    return [
      for (final entry in widget.items)
        if (widget.at(entry) case final String start when start.isNotEmpty) _CalendarEntry(entry, dtxCalendarDate(start), dtxCalendarDate(until?.call(entry) ?? start)),
    ];
  }

  List<DateTime> _days() {
    if (_mode == DtxCalendarMode.day) {
      return [_anchor];
    }
    final first = _mode == DtxCalendarMode.month ? _startOfWeek(DateTime(_anchor.year, _anchor.month)) : _startOfWeek(_anchor);
    final last = _mode == DtxCalendarMode.month ? _addDays(_startOfWeek(DateTime(_anchor.year, _anchor.month + 1, 0)), _daysPerWeek - 1) : _addDays(first, _daysPerWeek - 1);
    return [for (var day = first; !day.isAfter(last); day = _addDays(day, 1)) day];
  }

  bool _shows(DateTime date) {
    return switch (_mode) {
      DtxCalendarMode.month => date.year == _anchor.year && date.month == _anchor.month,
      DtxCalendarMode.week => _startOfWeek(date) == _startOfWeek(_anchor),
      DtxCalendarMode.day => date == _anchor,
    };
  }

  DateTime _shift(int direction) {
    return switch (_mode) {
      DtxCalendarMode.month => DateTime(_anchor.year, _anchor.month + direction),
      DtxCalendarMode.week => _addDays(_anchor, direction * _daysPerWeek),
      DtxCalendarMode.day => _addDays(_anchor, direction),
    };
  }

  void _turnTo(DateTime date) {
    setState(() {
      _anchor = date;
      _focused = date;
    });
  }

  void _focus(DateTime date) {
    setState(() {
      _focused = date;
      if (!_shows(date)) {
        _anchor = date;
      }
    });
  }

  KeyEventResult _key(FocusNode node, KeyEvent event) {
    if (event is! KeyDownEvent) {
      return KeyEventResult.ignored;
    }
    final step = _step(event.logicalKey);
    if (step != null) {
      _focus(_addDays(_focused, step));
      return KeyEventResult.handled;
    }
    if (event.logicalKey == LogicalKeyboardKey.home) {
      _focus(_startOfWeek(_focused));
    } else if (event.logicalKey == LogicalKeyboardKey.end) {
      _focus(_addDays(_startOfWeek(_focused), _daysPerWeek - 1));
    } else if (event.logicalKey == LogicalKeyboardKey.pageUp) {
      _turnTo(_shift(-1));
    } else if (event.logicalKey == LogicalKeyboardKey.pageDown) {
      _turnTo(_shift(1));
    } else {
      return KeyEventResult.ignored;
    }
    return KeyEventResult.handled;
  }

  Widget _toolbar(BuildContext context) {
    final locale = datrixRuntime.session.locale;
    return Wrap(
      spacing: DtxTokens.of(context).gap,
      crossAxisAlignment: WrapCrossAlignment.center,
      children: [
        TextButton(onPressed: () => _turnTo(_shift(-1)), child: Text(_text('framework.previous'))),
        TextButton(onPressed: () => _turnTo(_day(DateTime.now())), child: Text(_text('framework.today'))),
        TextButton(onPressed: () => _turnTo(_shift(1)), child: Text(_text('framework.next'))),
        Text(formatDate(_anchor, locale), style: Theme.of(context).textTheme.titleMedium),
        SegmentedButton<DtxCalendarMode>(
          segments: [for (final mode in DtxCalendarMode.values) ButtonSegment(value: mode, label: Text(_text('framework.${mode.name}')))],
          selected: {_mode},
          onSelectionChanged: (selected) => setState(() {
            _mode = selected.single;
            _anchor = _focused;
          }),
        ),
      ],
    );
  }

  Widget _cell(BuildContext context, DateTime date, List<_CalendarEntry<T>> entries) {
    final locale = datrixRuntime.session.locale;
    final activate = widget.onActivate;
    final inPeriod = _mode != DtxCalendarMode.month || date.month == _anchor.month;
    final focused = date == _focused;
    final scheme = Theme.of(context).colorScheme;
    final dayEntries = [
      for (final entry in entries)
        if (!date.isBefore(_day(entry.start)) && !date.isAfter(_day(entry.end))) entry,
    ];
    return Semantics(
      label: formatDate(date, locale),
      selected: focused,
      child: DecoratedBox(
        decoration: BoxDecoration(border: Border.all(color: focused && _grid.hasFocus ? scheme.primary : scheme.outlineVariant)),
        child: Opacity(
          opacity: inPeriod ? 1 : 0.5,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              ExcludeSemantics(child: Text('${date.day}', style: Theme.of(context).textTheme.labelSmall)),
              for (final entry in dayEntries) _activatable(widget.item(entry.item), activate == null ? null : () => activate(entry.item)),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final entries = _entries();
    final days = _days();
    final empty = widget.empty;
    final shown = entries.where((entry) => days.any((day) => !day.isBefore(_day(entry.start)) && !day.isAfter(_day(entry.end))));
    final weeks = [for (var start = 0; start < days.length; start += _daysPerWeek) days.sublist(start, (start + _daysPerWeek).clamp(0, days.length))];
    final grid = Focus(
      focusNode: _grid,
      onKeyEvent: _key,
      onFocusChange: (_) => setState(() {}),
      child: Semantics(
        label: formatDate(_anchor, datrixRuntime.session.locale),
        container: true,
        explicitChildNodes: true,
        child: Table(
          children: [
            for (final week in weeks) TableRow(children: [for (final day in week) _cell(context, day, entries)]),
          ],
        ),
      ),
    );
    final content = Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, spacing: DtxTokens.of(context).gap, children: [_toolbar(context), grid, if (shown.isEmpty && empty != null) _Empty(empty)]);
    return _paged(context, widget.style, content, widget.pager);
  }
}
